import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
    static final int M=998244353;
    static int n;
    static int[] h,b;
    static boolean ok(int l,int r,int x,int v){
        for(int i=h[v];i!=-1;i=b[i]){
            int p=Math.min(l,i)+Math.max(0,i-(n-r));
            int s=Math.min(r,n-i+1)+Math.max(0,l-i+1);
            boolean u=x<=i && p==(i-1)/2;
            boolean w=x>= i && s==(n-i)/2;
            if(!u && !w){
                return false;
            }
            
        }
        return true;
    }
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc=new Scanner(System.in);
		StringBuilder out=new StringBuilder();
		int t=sc.nextInt();
		
		while(t-- >0){
		    n=sc.nextInt();
		    h=new int[n+1];
		    b=new int[n+1];
		    Arrays.fill(h,-1);
		    
		    for(int i=1;i<=n;i++){
		        int x=sc.nextInt();
		        b[i]=h[x];
		        h[x]=i;
		        
		        
		    }
		    int[] d=new int[n+1];
		    int[] e=new int[n+1];
		    d[0]=1;
		    for(int v=1;v<=n;v++){
		        Arrays.fill(e,0);
		        for (int l=0;l<v;l++){
		            if(d[l]==0){
		                continue;
		            }
		            int r=v-1-l;
		            if(ok(l,r,l+1,v)){
		                e[l+1]+=d[l];
		                if(e[l+1]>=M){
		                    e[l+1]-=M;
		                }
		            }
		            if(v<n && ok(l,r,n-r,v)){
		                e[l]+=d[l];
		                if(e[l]>=M){
		                    e[l]-=M;
		                }
		            }
		        }
		        int[] q=d;
		        d=e;
		        e=q;
		    }
		    int ans=0;
		    for(int x:d){
		        ans+=x;
		        if(ans>=M){
		            ans-=M;
		        }
		    }
		    out.append(ans).append('\n');
		}
        System.out.print(out);
        sc.close();
	}
}
